/**
 * WISDOM BANK C — hatha_yoga_pradipika, bhagavata_purana. Compact real entries.
 */

import type { WisdomArchetype } from "./types";

export const WISDOM_HATHA_YOGA_PRADIPIKA: WisdomArchetype[] = [
  { concept: "Hatha as the Staircase to Raja", tradition: "Hatha Yoga Pradipika", source: "HYP 1.2", explanation: "The Hatha Yoga Pradipika opens by saluting Shiva, who taught hatha yoga as a staircase to the highest raja yoga. Hatha is not an end but a preparation — the body's discipline makes the mind's stillness possible.", application: "Treat every asana and breath practice as staircase-building, not destination. The measure of hatha practice is not flexibility but the mind's increasing capacity to sit still.", questions: ["Is my physical practice building the staircase or decorating it?", "What would 'preparation for raja' change in my next session?", "Where is my practice's end — the body or the still mind?"], references: ["Hatha Yoga Pradipika 1.1-1.2", "Hatha Yoga Pradipika 1.3-1.4"], excerpt: "Salutation to Shiva, who taught hatha yoga as a staircase to raja yoga.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "raja"], domains: ["learning", "spirituality"], tags: ["hyp", "hatha", "raja", "staircase", "preparation"], difficulty: "beginner", minutes: 5 },
  { concept: "The Ten Yamas and Ten Niyamas", tradition: "Hatha Yoga Pradipika", source: "HYP 1.17-1.20", explanation: "The HYP expands Patanjali's five yamas and five niyamas to ten each — adding non-injury's companions: forgiveness, honesty, compassion, generosity, and more. The ethical frame is presented as the body practice's foundation, not its ornament.", application: "Before deepening any physical practice, audit the ethical frame. The text's logic: a body trained without ethics becomes a stronger vehicle for the same patterns.", questions: ["Which of the ten yamas is most absent in my practice life?", "Is my body practice ahead of my ethical practice?", "What would forgiveness-as-yama change in my training?"], references: ["Hatha Yoga Pradipika 1.17-1.20", "Yoga Sutras 2.30-2.32"], excerpt: "The ten yamas: non-injury, truth, non-stealing, continence, non-possessiveness, forgiveness, honesty, compassion, generosity, moderation.", evidence: "traditional", dimensions: ["action", "thought"], paths: ["hatha", "raja"], domains: ["ethics", "growth"], tags: ["hyp", "yamas", "niyamas", "ten", "ethics", "foundation"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Fifteen Asanas — Svastikasana First", tradition: "Hatha Yoga Pradipika", source: "HYP 1.27-1.35", explanation: "The HYP names fifteen classical asanas, beginning with svastikasana (the auspicious seat) and including siddhasana, padmasana, and the celebrated matsyendrasana. The text treats asana as the first of hatha's limbs — steady, comfortable, disease-destroying.", application: "Return to the fifteen as a curriculum: one asana per week, studied rather than performed. The text's asanas are seats for breath and meditation, not gymnastics.", questions: ["Which of the fifteen asanas do I actually practice?", "Is my asana practice a seat for meditation or a workout?", "What would studying one asana for a week reveal?"], references: ["Hatha Yoga Pradipika 1.27-1.35", "Hatha Yoga Pradipika 1.36-1.40"], excerpt: "Svastikasana, siddhasana, padmasana — the first seats of the hatha yogi.", evidence: "traditional", dimensions: ["body", "thought"], paths: ["hatha"], domains: ["health", "learning"], tags: ["hyp", "asana", "fifteen", "svastikasana", "siddhasana", "padmasana"], difficulty: "beginner", minutes: 6 },
  { concept: "Siddhasana — The Accomplisher's Seat", tradition: "Hatha Yoga Pradipika", source: "HYP 1.37-1.45", explanation: "The HYP's most praised asana: siddhasana, the accomplished one's seat. The text claims it destroys all diseases and, when mastered with the bandhas, opens the door to samadhi. Its mechanism: the perineum's pressure and the spine's verticality.", application: "If you can sit in siddhasana comfortably for three hours, the text says, there is no need for other asanas. Test the claim modestly: does this seat stabilize your breath and attention more than your current seat?", questions: ["What is my current seat — and what does it stabilize?", "What would the accomplished one's seat change about my sitting?", "Can I sit still for thirty minutes — and if not, what is in the way?"], references: ["Hatha Yoga Pradipika 1.37-1.45", "Hatha Yoga Pradipika 1.46-1.50"], excerpt: "Siddhasana destroys all diseases and opens the door to samadhi.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha"], domains: ["health", "spirituality"], tags: ["hyp", "siddhasana", "seat", "accomplished", "samadhi"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Yogic Diet — Mitahara", tradition: "Hatha Yoga Pradipika", source: "HYP 1.58-1.63", explanation: "The HYP's dietary teaching: moderate, sweet, nourishing food — leaving a quarter empty, filling a quarter with water, and half with food. The text lists foods to avoid (bitter, sour, salty, heating) and foods to favor (milk, ghee, honey, wheat).", application: "The yogic diet is not a prescription but a principle: eat for the seat's stability. Test mitahara for one week — three-quarters full, gentle foods — and observe the effect on sitting.", questions: ["What is my current eating pattern's effect on my sitting?", "What would three-quarters-full look like today?", "Which foods agitate my practice — and which support it?"], references: ["Hatha Yoga Pradipika 1.58-1.63", "Hatha Yoga Pradipika 1.64-1.67"], excerpt: "Leave a quarter empty, fill a quarter with water, half with food — the yogi's measure.", evidence: "traditional", dimensions: ["body", "action"], paths: ["hatha"], domains: ["health"], tags: ["hyp", "diet", "mitahara", "moderate", "food", "quarter"], difficulty: "beginner", minutes: 6 },
  { concept: "The Shatkarmas — Six Purifications", tradition: "Hatha Yoga Pradipika", source: "HYP 2.21-2.35", explanation: "The HYP's second chapter teaches the six purifications (shatkarmas): dhauti (cleansing), basti (colon), neti (nasal), trataka (gazing), nauli (abdominal churning), and kapalabhati (skull-shining). The text presents them as preparation for pranayama — the body's gross impurities removed first.", application: "The shatkarmas are the library's most physical entries. Approach them with the text's own caution: they are for the dull, the fat, and the phlegmatic — the constitutionally blocked. Healthy, balanced practitioners may need only trataka and kapalabhati.", questions: ["Which purification, if any, does my constitution need?", "Am I practicing shatkarmas for preparation or for spectacle?", "What is the text's own caution about who needs them?"], references: ["Hatha Yoga Pradipika 2.21-2.35", "Hatha Yoga Pradipika 2.36-2.40"], excerpt: "The six purifications: dhauti, basti, neti, trataka, nauli, kapalabhati.", evidence: "traditional", dimensions: ["body", "thought"], paths: ["hatha", "kriya"], domains: ["health"], tags: ["hyp", "shatkarmas", "purification", "dhauti", "neti", "trataka", "nauli", "kapalabhati"], difficulty: "advanced", minutes: 8 },
  { concept: "Pranayama's Preparation — The Nadis", tradition: "Hatha Yoga Pradipika", source: "HYP 2.1-2.10", explanation: "Before pranayama, the HYP teaches, the nadis must be purified. The text maps 72,000 nadis, of which fourteen are principal, and three are central: ida (moon, left), pingala (sun, right), and sushumna (the central channel). Pranayama's purpose is to open sushumna.", application: "The nadi teaching gives breathwork its anatomy: alternate nostril breathing balances ida and pingala; the goal is sushumna's opening — the central channel of stillness.", questions: ["Which nadi dominates my current state — lunar (calm) or solar (active)?", "What is my practice's relationship to the central channel?", "Can I feel the difference between balancing and opening?"], references: ["Hatha Yoga Pradipika 2.1-2.10", "Hatha Yoga Pradipika 2.11-2.20"], excerpt: "72,000 nadis; fourteen principal; three central — ida, pingala, sushumna.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "kriya"], domains: ["health", "learning"], tags: ["hyp", "nadis", "ida", "pingala", "sushumna", "pranayama", "preparation"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Eight Kumbhakas", tradition: "Hatha Yoga Pradipika", source: "HYP 2.49-2.67", explanation: "The HYP's third chapter teaches eight kumbhakas — breath retentions: surya bhedana, ujjayi, sheetkari, sheetali, bhastrika, bhramari, moorcha, and plavini. Each is described with its technique, its effects, and its cautions. The text treats retention as pranayama's heart.", application: "The eight kumbhakas are the library's breathwork backbone. Study them one at a time — the text's own pace. Each has a specific effect: heating, cooling, calming, energizing, dissolving.", questions: ["Which of the eight kumbhakas have I actually practiced?", "What is my constitution's appropriate retention — heating or cooling?", "Where is the text's caution in my current practice?"], references: ["Hatha Yoga Pradipika 2.49-2.67", "Hatha Yoga Pradipika 2.68-2.73"], excerpt: "The eight kumbhakas: surya bhedana, ujjayi, sheetkari, sheetali, bhastrika, bhramari, moorcha, plavini.", evidence: "traditional", dimensions: ["body", "thought"], paths: ["hatha", "kriya"], domains: ["health", "learning"], tags: ["hyp", "kumbhaka", "retention", "eight", "ujjayi", "bhastrika", "bhramari"], difficulty: "advanced", minutes: 9 },
  { concept: "The Gradual Progression — Like a Lion Tamed", tradition: "Hatha Yoga Pradipika", source: "HYP 2.15-2.16", explanation: "The HYP's famous caution: pranayama should be practiced gradually, like a lion, tiger, or bear tamed step by step. The text warns that hasty, forceful practice destroys the practitioner — the very energy sought is the energy that harms.", application: "The gradual-progression teaching is the library's safety backbone. Every breathwork entry inherits it: build slowly, respect the cautions, and treat force as the enemy of the practice it intends to serve.", questions: ["Where is my practice hasty rather than gradual?", "What is the lion in my practice — the energy I am trying to tame?", "What would 'step by step' look like this month?"], references: ["Hatha Yoga Pradipika 2.15-2.16", "Hatha Yoga Pradipika 2.17-2.20"], excerpt: "Practice gradually, like a lion tamed step by step. Hasty practice destroys.", evidence: "traditional", dimensions: ["body", "thought", "action"], paths: ["hatha", "kriya"], domains: ["health", "safety"], tags: ["hyp", "gradual", "progression", "lion", "caution", "safety"], difficulty: "beginner", minutes: 5 },
  { concept: "The Mudras — Ten Seals", tradition: "Hatha Yoga Pradipika", source: "HYP 3.1-3.32", explanation: "The HYP's third chapter teaches the ten mudras — seals that redirect energy: maha, khechari, viparita karani, vajroli, shakti chalini, yoni, shambhavi, unmani, khechari, and the bandhas. The text presents them as advanced practices requiring a teacher.", application: "The mudra teaching is the library's clearest statement on teacher-guidance: these practices are not self-taught from text. The application is humility — knowing which practices require transmission.", questions: ["Which practices am I attempting without transmission?", "What is the difference between a seal and a technique?", "Where is my practice's appropriate boundary — and who set it?"], references: ["Hatha Yoga Pradipika 3.1-3.32", "Hatha Yoga Pradipika 3.33-3.40"], excerpt: "The ten mudras — seals to be learned from a teacher, not a text.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "kriya", "tantra"], domains: ["learning", "spirituality"], tags: ["hyp", "mudras", "seals", "teacher", "transmission", "advanced"], difficulty: "advanced", minutes: 8 },
  { concept: "The Bandhas — Three Locks", tradition: "Hatha Yoga Pradipika", source: "HYP 3.61-3.73", explanation: "The HYP teaches the three bandhas — mula (root lock), uddiyana (abdominal lock), and jalandhara (throat lock) — as the mechanisms that direct prana into the central channel. The text's image: the bandhas are the locks that open sushumna's door.", application: "Learn the three locks as anatomy, not mysticism: root lock engages the pelvic floor, abdominal lock draws the abdomen in, throat lock drops the chin. Their combination in practice is the library's most precise energetic technique.", questions: ["Can I locate and engage each of the three locks?", "What is the difference between a lock and a clench?", "Where do the locks direct my prana — and can I feel it?"], references: ["Hatha Yoga Pradipika 3.61-3.73", "Hatha Yoga Pradipika 3.74-3.80"], excerpt: "The three bandhas — root, abdominal, throat — the locks that open the central channel.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "kriya"], domains: ["health", "learning"], tags: ["hyp", "bandhas", "mula", "uddiyana", "jalandhara", "locks"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Sound of Anahata — The Unstruck Sound", tradition: "Hatha Yoga Pradipika", source: "HYP 4.78-4.90", explanation: "The HYP's fourth chapter teaches nada yoga — the yoga of sound. The practitioner closes the ears and listens to the inner sound, which begins as loud and gradually becomes subtle, until the unstruck sound (anahata) remains. The text maps ten stages of sound.", application: "Nada yoga is the library's most accessible advanced practice: close the ears, listen inwardly, follow the sound's subtler and subtler layers. The practice requires only silence and patience.", questions: ["What inner sounds are present when I listen in silence?", "Can I follow a sound from loud to subtle?", "What is the unstruck sound — and can I distinguish it from imagination?"], references: ["Hatha Yoga Pradipika 4.78-4.90", "Hatha Yoga Pradipika 4.91-4.114"], excerpt: "Close the ears and listen. The sound becomes subtle, until the unstruck sound remains.", evidence: "traditional", dimensions: ["thought", "spirit", "body"], paths: ["raja", "kriya"], domains: ["spirituality", "learning"], tags: ["hyp", "nada", "anahata", "unstruck_sound", "inner_sound", "listening"], difficulty: "advanced", minutes: 9 },
  { concept: "The Dissolution of the Mind — Laya", tradition: "Hatha Yoga Pradipika", source: "HYP 4.44-4.50", explanation: "The HYP's fourth chapter teaches laya — dissolution. When the mind dissolves into the self, like salt in water, the practitioner rests in the state beyond mind and no-mind. The text presents laya as the natural fruit of the preceding practices.", application: "Laya is the library's teaching on practice's endpoint: not a new state but a dissolution of the one that asks. The application is paradoxical — practice diligently, then let the practitioner dissolve.", questions: ["What is the difference between dissolving the mind and suppressing it?", "Where is my practice's endpoint — a state or a dissolution?", "Can I practice without a practitioner — and what would that feel like?"], references: ["Hatha Yoga Pradipika 4.44-4.50", "Hatha Yoga Pradipika 4.51-4.60"], excerpt: "The mind dissolves like salt in water — laya, the dissolution.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["raja", "kriya"], domains: ["spirituality"], tags: ["hyp", "laya", "dissolution", "salt", "mind", "endpoint"], difficulty: "advanced", minutes: 8 },
  { concept: "The Four Stages of Speech", tradition: "Hatha Yoga Pradipika", source: "HYP 4.1-4.10", explanation: "The HYP's fourth chapter opens with the four stages of speech: para (the highest, unmanifest), pashyanti (the seen), madhyama (the intermediate), and vaikhari (the spoken). The teaching maps sound from its unmanifest source to its gross utterance.", application: "The four stages give mantra practice its depth: japa begins in vaikhari (spoken), moves to madhyama (whispered), pashyanti (seen), and para (unmanifest). The practice is the descent into sound's source.", questions: ["At which stage does my mantra practice operate?", "What is the difference between sound's source and sound's utterance?", "Can I follow a mantra from speech to silence?"], references: ["Hatha Yoga Pradipika 4.1-4.10", "Nada Bindu Upanishad"], excerpt: "The four stages of speech: para, pashyanti, madhyama, vaikhari.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja", "kriya"], domains: ["learning", "spirituality"], tags: ["hyp", "speech", "four_stages", "para", "pashyanti", "madhyama", "vaikhari"], difficulty: "advanced", minutes: 8 },
  { concept: "The Guru's Necessity", tradition: "Hatha Yoga Pradipika", source: "HYP 1.23-1.25", explanation: "The HYP repeatedly insists: hatha yoga is not learned from books. The text itself is a summary for those who already have a teacher. The tradition's stance is not anti-intellectual but protective — the practices are powerful and the errors are silent.", application: "The library inherits the HYP's stance: entries are pointers, not transmissions. The application is the discipline of knowing when text ends and teacher begins — especially for the advanced practices.", questions: ["Which of my practices need a teacher, and which are safe from text?", "Where is text substituting for transmission in my life?", "What is the difference between a pointer and a transmission?"], references: ["Hatha Yoga Pradipika 1.23-1.25", "Hatha Yoga Pradipika 3.1-3.5"], excerpt: "Hatha yoga is not learned from books. The text is a summary for those with a teacher.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["hatha", "raja"], domains: ["learning", "spirituality"], tags: ["hyp", "guru", "teacher", "transmission", "books", "pointer"], difficulty: "beginner", minutes: 5 },
  { concept: "The Six Chakras and the Kundalini's Ascent", tradition: "Hatha Yoga Pradipika", source: "HYP 3.1-3.20; 4.1-4.20", explanation: "The HYP maps the subtle body: the six chakras (plus the sahasrara above), the kundalini coiled at the base, and the sushumna channel through which she rises. The text's account is the classical template for all chakra literature that follows.", application: "Use the HYP's map as the library's chakra reference frame: six centers plus the crown, the serpent at the base, the central channel. Every chakra entry in this library inherits this map's vocabulary.", questions: ["Can I locate the six chakras and the sahasrara?", "What is the kundalini's relationship to my practice — aspiration or pressure?", "What is the central channel, and where is it felt?"], references: ["Hatha Yoga Pradipika 3.1-3.20", "Hatha Yoga Pradipika 4.1-4.20", "Shat-Chakra-Nirupana"], excerpt: "Six chakras, the coiled kundalini, and the sushumna — the classical map.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "kriya", "tantra"], domains: ["spirituality", "learning"], tags: ["hyp", "chakras", "kundalini", "sushumna", "ascent", "six"], difficulty: "intermediate", minutes: 8 },
  { concept: "Khechari Mudra — The Seal of the Void", tradition: "Hatha Yoga Pradipika", source: "HYP 3.32-3.43", explanation: "The HYP's most celebrated advanced mudra: khechari, the seal of the void, involving the tongue's lengthening and turning backward into the nasal cavity. The text claims it binds the mind, grants clairvoyance, and delays aging. The teaching is presented with elaborate preparation rituals.", application: "Khechari is the library's boundary case: a practice the tradition itself guards. The application is not the technique but the lesson — some practices are guarded for reasons of safety, readiness, and transmission. Respect the boundary.", questions: ["Why do traditions guard certain practices?", "What is the difference between curiosity and readiness?", "What in my practice is guarded, and by whom?"], references: ["Hatha Yoga Pradipika 3.32-3.43", "Hatha Yoga Pradipika 3.44-3.50"], excerpt: "Khechari mudra — the seal of the void, guarded and gradual.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "kriya", "tantra"], domains: ["spirituality", "learning"], tags: ["hyp", "khechari", "mudra", "guarded", "advanced", "boundary"], difficulty: "advanced", minutes: 8 },
  { concept: "Vajroli Mudra — The Thunderbolt Seal", tradition: "Hatha Yoga Pradipika", source: "HYP 3.82-3.89", explanation: "The HYP's most controversial teaching: vajroli mudra, the thunderbolt seal, involving the retention and redirection of sexual fluid. The text presents it as the highest of the mudras, requiring a teacher and years of preparation. The tradition's stance is unambiguous: guarded, gradual, transmitted.", application: "Vajroli is the library's clearest case for the ingestion pipeline's review status: some content is published with explicit guidance that it requires transmission. The application is the discipline of restraint — in text and in practice.", questions: ["What is the tradition's stance on guarded practices?", "Where does my curiosity outrun my readiness?", "What does 'requires a teacher' mean for my practice?"], references: ["Hatha Yoga Pradipika 3.82-3.89", "Hatha Yoga Pradipika 3.90-3.95"], excerpt: "Vajroli mudra — the thunderbolt seal, highest of the mudras, requiring a teacher.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "kriya", "tantra"], domains: ["spirituality", "ethics"], tags: ["hyp", "vajroli", "mudra", "guarded", "thunderbolt", "transmission"], difficulty: "advanced", minutes: 7 },
  { concept: "The Amrita and the Bindu", tradition: "Hatha Yoga Pradipika", source: "HYP 3.10-3.20", explanation: "The HYP's subtle physiology: the bindu (seed) resides in the head, the amrita (nectar) drips from the moon center above the palate, and the fire below consumes it. The text's teaching: preserving and reversing the flow is hatha yoga's core alchemy.", application: "The amrita teaching is the library's entry into subtle physiology — presented as the tradition's own model, not as modern anatomy. The application is the model's use: attention to the head-palate-abdomen axis in practice.", questions: ["What is the tradition's model of subtle physiology?", "How does the amrita teaching relate to my practice's felt sense?", "Where is the tradition's model useful, and where does it end?"], references: ["Hatha Yoga Pradipika 3.10-3.20", "Hatha Yoga Pradipika 3.21-3.30"], excerpt: "The bindu in the head, the amrita dripping from the moon, the fire below.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "kriya"], domains: ["learning", "spirituality"], tags: ["hyp", "amrita", "bindu", "nectar", "moon", "fire", "subtle_physiology"], difficulty: "advanced", minutes: 8 },
  { concept: "The Sun and the Moon — Ida and Pingala", tradition: "Hatha Yoga Pradipika", source: "HYP 2.1-2.10; 4.1-4.10", explanation: "The HYP's core energetic model: the moon (ida, left, lunar, cooling) and the sun (pingala, right, solar, heating) flow through the body's two side channels. Hatha itself means sun-moon — the union of the two. The text's practices aim at their balance and union.", application: "The sun-moon model is the library's most practical energetic diagnostic: notice which channel is dominant (active/heat vs. calm/cool), and practice to balance. Alternate nostril breathing is the direct technique.", questions: ["Which channel dominates right now — solar or lunar?", "What is my practice's effect on the balance?", "What does 'hatha' — sun-moon — mean for my practice's purpose?"], references: ["Hatha Yoga Pradipika 2.1-2.10", "Hatha Yoga Pradipika 4.1-4.10"], excerpt: "Ha is the sun, tha is the moon. Hatha yoga is their union.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "kriya"], domains: ["learning", "health"], tags: ["hyp", "sun", "moon", "ida", "pingala", "hatha", "union"], difficulty: "beginner", minutes: 6 },
  { concept: "The Samadhi of the Hatha Yogi", tradition: "Hatha Yoga Pradipika", source: "HYP 4.1-4.10", explanation: "The HYP's fourth chapter describes the hatha yogi's samadhi: the mind dissolved, the breath suspended, the body forgotten. The text's final teaching is that hatha's physical practices exist for this — the dissolution they prepare.", application: "The HYP's arc is the library's arc: body, breath, seal, sound, dissolution. Every physical entry in this library serves the final chapter. The application is the arc's integrity — no practice without its horizon.", questions: ["What is my practice's horizon — the dissolution it prepares?", "Where is my practice's arc broken — body without breath, breath without stillness?", "What would the hatha yogi's samadhi mean for my daily sitting?"], references: ["Hatha Yoga Pradipika 4.1-4.10", "Hatha Yoga Pradipika 4.11-4.20"], excerpt: "The hatha yogi's samadhi: mind dissolved, breath suspended, body forgotten.", evidence: "traditional", dimensions: ["spirit", "body", "thought"], paths: ["hatha", "raja"], domains: ["spirituality"], tags: ["hyp", "samadhi", "dissolution", "suspended_breath", "horizon"], difficulty: "advanced", minutes: 9 },
  { concept: "The HYP's Lineage — Matsyendranath to Gorakshanath", tradition: "Hatha Yoga Pradipika", source: "HYP 1.1-1.10", explanation: "The HYP opens its teaching lineage: Shiva taught Matsyendranath, who taught Gorakshanath, who taught the text's compiler Svatmarama. The lineage is the tradition's claim of transmission — the practices are received, not invented.", application: "The lineage teaching applies to this library: content is received from traditions, adapted with attribution. The application is provenance — every entry names its source, and the sources name theirs.", questions: ["What is my practice's lineage — received from whom?", "How does provenance change my relationship to the teaching?", "What is the difference between received practice and invented technique?"], references: ["Hatha Yoga Pradipika 1.1-1.10", "Goraksha Shatakam", "Matsyendrasamhita"], excerpt: "Shiva to Matsyendra, Matsyendra to Goraksha, Goraksha to Svatmarama — the lineage.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["hatha", "kriya"], domains: ["learning", "spirituality"], tags: ["hyp", "lineage", "matsyendra", "goraksha", "svatmarama", "transmission"], difficulty: "beginner", minutes: 5 },
  { concept: "The Yoga of the Body's Forgotten Intelligence", tradition: "Hatha Yoga Pradipika", source: "HYP 1.15-1.20", explanation: "The HYP's underlying premise: the body is not an obstacle to awakening but its instrument. The text's asanas, purifications, and breath practices treat the body as intelligent — capable of purification, stabilization, and revelation. This premise distinguishes hatha from purely ascetic approaches.", application: "The premise is the library's somatic foundation: the body is trained, not punished. Every somatic and breathwork entry inherits this stance — the body as instrument, the practice as tuning.", questions: ["Do I treat my body as obstacle or instrument?", "What would tuning (not punishing) look like this week?", "Where is my body's forgotten intelligence in my current practice?"], references: ["Hatha Yoga Pradipika 1.15-1.20", "Hatha Yoga Pradipika 1.21-1.25"], excerpt: "The body is the instrument of awakening — trained, not punished.", evidence: "traditional", dimensions: ["body", "thought", "spirit"], paths: ["hatha", "tantra"], domains: ["health", "growth"], tags: ["hyp", "body", "instrument", "intelligence", "tuning", "premise"], difficulty: "beginner", minutes: 5 },
  { concept: "The Warning Against Premature Practice", tradition: "Hatha Yoga Pradipika", source: "HYP 2.15-2.16; 3.1-3.5", explanation: "The HYP's repeated warning: premature or forceful practice — especially of pranayama, bandhas, and mudras — harms the practitioner. The text specifies who should practice what, when, and under what conditions. The warnings are not footnotes; they are the teaching.", application: "The library's safety notes inherit the HYP's warnings directly. The application is the discipline of reading cautions before techniques — and the humility to wait for readiness.", questions: ["Have I read the cautions before the techniques?", "Where is my practice premature — ahead of readiness?", "What is the cost of skipping the warning?"], references: ["Hatha Yoga Pradipika 2.15-2.16", "Hatha Yoga Pradipika 3.1-3.5"], excerpt: "Premature or forceful practice harms. Read the warnings — they are the teaching.", evidence: "traditional", dimensions: ["thought", "body", "action"], paths: ["hatha", "kriya"], domains: ["safety", "health", "learning"], tags: ["hyp", "warning", "premature", "forceful", "safety", "readiness"], difficulty: "beginner", minutes: 5 },
  { concept: "The Fruit — Freedom in This Body", tradition: "Hatha Yoga Pradipika", source: "HYP 4.1-4.10", explanation: "The HYP's final promise: the hatha yogi attains freedom in this very body — not after death, not in another realm, but here. The text's closing teaching is embodied liberation: the body itself becomes the site of the dissolution it prepared.", application: "The promise is the library's horizon: freedom in this body, this life, this moment. The application is the practices' integration — body, breath, mind, and witness as one continuous arc.", questions: ["What would freedom in this body look like — concretely, today?", "Where is my practice preparing for elsewhere instead of here?", "What is the relationship between the body's freedom and the mind's?"], references: ["Hatha Yoga Pradipika 4.1-4.10", "Hatha Yoga Pradipika 4.11-4.20"], excerpt: "The hatha yogi attains freedom in this very body.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["hatha", "raja"], domains: ["spirituality", "health"], tags: ["hyp", "freedom", "this_body", "embodied", "liberation", "fruit"], difficulty: "advanced", minutes: 8 },
];

export const WISDOM_BHAGAVATA_PURANA: WisdomArchetype[] = [
  { concept: "The Nine Forms of Devotion — Navavidha Bhakti", tradition: "Bhagavata Purana", source: "Bhagavata Purana 7.5.23-24", explanation: "The Bhagavata's most influential teaching: nine forms of devotion — hearing (shravana), praising (kirtana), remembering (smarana), serving (pada-sevana), worshiping (archana), saluting (vandana), serving the lotus feet (dasya), friendship (sakhya), and self-surrender (atma-nivedana). The complete yoga of the heart.", application: "Use the nine forms as a devotional curriculum: which form is natural, which is absent? The text's logic — all nine are paths, not requirements; begin where the heart already moves.", questions: ["Which of the nine forms is most natural to me?", "Which is absent — and what would one small act of it look like?", "Is my devotion a feeling or a practice — and does the difference matter?"], references: ["Bhagavata Purana 7.5.23-24", "Bhagavata Purana 11.2.46"], excerpt: "Hearing, praising, remembering, serving, worshiping, saluting, devotion, friendship, surrender — the nine forms.", evidence: "traditional", dimensions: ["emotion", "spirit", "connection"], paths: ["bhakti"], domains: ["spirituality", "growth"], tags: ["bhagavata", "navavidha", "nine_forms", "bhakti", "devotion", "hearing", "surrender"], difficulty: "beginner", minutes: 7 },
  { concept: "The Story of Prahlada — Devotion Under Fire", tradition: "Bhagavata Purana", source: "Bhagavata Purana 7.1-7.5", explanation: "The Bhagavata's most celebrated narrative: Prahlada, the five-year-old devotee, survives his demon-father Hiranyakashipu's every attempt to kill him — poison, elephants, fire, ocean, serpent. The teaching: devotion is not protected from danger; it is protected through danger.", application: "Prahlada's story is the library's core adversity teaching. The application is not the drama but the pattern: the fire that does not burn, the poison that does not harm — the devotee's protection is the devotion itself, not the absence of threat.", questions: ["What is my current fire — and what is my relationship to it?", "What would 'protected through, not from' look like this week?", "Where is my devotion tested — and what does the test reveal?"], references: ["Bhagavata Purana 7.1-7.5", "Bhagavata Purana 7.6-7.10"], excerpt: "The fire did not burn the devotee. The devotion was the protection.", evidence: "traditional", dimensions: ["emotion", "spirit", "thought"], paths: ["bhakti"], domains: ["growth", "spirituality"], tags: ["bhagavata", "prahlada", "devotion", "fire", "protection", "adversity"], difficulty: "beginner", minutes: 8 },
  { concept: "The Story of Dhruva — The Unwavering", tradition: "Bhagavata Purana", source: "Bhagavata Purana 4.8-4.12", explanation: "Young Dhruva, insulted by his stepmother and denied his father's throne, walks into the forest to find the Lord — or death. His meditation is so unwavering that Vishnu appears and grants him the pole star — the fixed point around which all heavens turn. The origin of the word 'dhruva' — fixed, unwavering.", application: "Dhruva's story teaches the library's attention foundation: the fixed point. The application is literal — choose one object of attention and be unwavering, not because success is guaranteed but because unwaveringness itself is the transformation.", questions: ["What is my fixed point — my dhruva?", "Where is my attention unwaveringly placed, and where is it scattered?", "What would the pole star's steadiness mean for my practice?"], references: ["Bhagavata Purana 4.8-4.12", "Bhagavata Purana 4.13"], excerpt: "Dhruva became the pole star — the fixed point around which all heavens turn.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["bhakti", "raja"], domains: ["growth", "spirituality"], tags: ["bhagavata", "dhruva", "unwavering", "pole_star", "fixed_point", "attention"], difficulty: "beginner", minutes: 7 },
  { concept: "The Story of Markandeya — The Eternal Child", tradition: "Bhagavata Purana", source: "Bhagavata Purana 12.4-12.5", explanation: "The sage Markandeya, destined to die at sixteen, clings to the Shiva linga as Yama's messengers come. Shiva emerges, strikes down Yama, and grants Markandeya eternal youth — the deathless child. The Bhagavata's teaching on grace beyond destiny.", application: "Markandeya's story teaches surrender's extremity: the clinging is not to a ritual object but to the one who is beyond death. The application is the recognition that what we cling to in crisis reveals what we actually worship.", questions: ["What do I cling to in crisis — and what does that reveal?", "What is my relationship to destiny — acceptance or defiance?", "Where is grace beyond effort, in my experience?"], references: ["Bhagavata Purana 12.4-12.5", "Mahabharata, Vana Parva"], excerpt: "The child clung to the linga; death was struck down. Grace beyond destiny.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["bhakti"], domains: ["spirituality", "growth"], tags: ["bhagavata", "markandeya", "eternal_child", "grace", "destiny", "surrender"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Story of Ajamila — Grace at the Threshold", tradition: "Bhagavata Purana", source: "Bhagavata Purana 6.1-6.3", explanation: "Ajamila, a fallen Brahmin, dies calling his son's name 'Narayana' — the name of the Lord. The messengers of Yama come; the Vishnudutas intervene, arguing that even an accidental utterance of the name purifies. The Bhagavata's radical teaching on the name's power and grace's reach.", application: "Ajamila's story is the library's mercy teaching: the name's power is not reserved for the worthy. The application is not moral laxity but hope — the practice of the name is available at every threshold, including the last.", questions: ["What is my relationship to worthiness — do I believe practice requires perfection?", "Where is grace's reach in my understanding?", "What is the power of the name, in my own tradition's terms?"], references: ["Bhagavata Purana 6.1-6.3", "Bhagavata Purana 6.4"], excerpt: "He died calling 'Narayana' — and the messengers of the Lord intervened.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["bhakti"], domains: ["spirituality", "growth"], tags: ["bhagavata", "ajamila", "grace", "name", "threshold", "mercy"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Story of Gajendra — The Elephant's Cry", tradition: "Bhagavata Purana", source: "Bhagavata Purana 8.2-8.4", explanation: "King Gajendra, the elephant, is seized by a crocodile in the lake. After a hundred years of struggle, he calls out to the Lord with a lotus flower — and is rescued. The Bhagavata's teaching: the cry of the helpless is the highest prayer. The crocodile is the ego; the lake is the world.", application: "Gajendra's story teaches the library's crisis practice: when struggle has exhausted every strategy, the cry itself is the practice. The application is not passivity but the recognition that the cry is heard — and that the lotus in the hand is enough.", questions: ["What is my current crocodile — and how long have I struggled?", "What is in my hand — my lotus — right now?", "What is the difference between the cry of the helpless and the cry of the lazy?"], references: ["Bhagavata Purana 8.2-8.4", "Bhagavata Purana 8.5"], excerpt: "The elephant's cry, after a hundred years, was heard. The lotus was enough.", evidence: "traditional", dimensions: ["emotion", "spirit"], paths: ["bhakti"], domains: ["spirituality", "growth"], tags: ["bhagavata", "gajendra", "elephant", "crocodile", "cry", "lotus", "helpless"], difficulty: "beginner", minutes: 7 },
  { concept: "The Story of Bali — The Generous Demon", tradition: "Bhagavata Purana", source: "Bhagavata Purana 8.18-8.24", explanation: "King Bali, the demon-king whose generosity was legendary, is approached by Vamana, the dwarf avatar, who asks three paces of land. Bali grants it; Vamana grows, covers the worlds in two steps, and places the third on Bali's head — sending him to the netherworld, but granting him the position of future Indra. The teaching: generosity meets its match in the divine, and even downfall carries dignity.", application: "Bali's story teaches the library's lesson on limits: generosity is a virtue, but the infinite cannot be contained by the finite. The application is the recognition of where my giving ends and the divine's begins.", questions: ["Where is my generosity running ahead of my wisdom?", "What is the difference between giving everything and giving what is mine to give?", "Can I hold Bali's dignity — downfall with grace?"], references: ["Bhagavata Purana 8.18-8.24", "Bhagavata Purana 8.25"], excerpt: "Three paces of land. The dwarf grew. Generosity met its match.", evidence: "traditional", dimensions: ["action", "spirit", "thought"], paths: ["bhakti", "karma"], domains: ["growth", "ethics"], tags: ["bhagavata", "bali", "vamana", "generosity", "limits", "dignity"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Story of Krishna's Childhood — The Butter Thief", tradition: "Bhagavata Purana", source: "Bhagavata Purana 10.8-10.9", explanation: "The Bhagavata's most beloved narratives: Krishna the butter thief, stealing curds and butter, breaking the pots, covering himself in white — and the gopis' futile complaints to Mother Yashoda, who finds him covered in butter, smiling. The teaching: the divine is not above mischief; the divine is the mischief.", application: "The butter-thief stories teach the library's playful dimension: devotion is not solemnity. The application is the permission to play — to let the practice include laughter, mischief, and the breaking of a few pots.", questions: ["Where is my practice too solemn for its own good?", "What would the butter thief's playfulness look like in my discipline?", "Can I hold discipline and mischief in one hand?"], references: ["Bhagavata Purana 10.8-10.9", "Bhagavata Purana 10.10-10.13"], excerpt: "The butter thief, covered in white, smiling. The gopis complained; the divine played.", evidence: "traditional", dimensions: ["emotion", "spirit"], paths: ["bhakti"], domains: ["spirituality", "growth"], tags: ["bhagavata", "krishna", "butter_thief", "playfulness", "mischief", "childhood"], difficulty: "beginner", minutes: 6 },
  { concept: "The Gopi's Love — The Highest Devotion", tradition: "Bhagavata Purana", source: "Bhagavata Purana 10.29-10.33", explanation: "The Bhagavata's most esoteric teaching: the gopis' love for Krishna — the rasa dance, the moonlit forest, the longing without possession. The text presents their love as the highest devotion: not for reward, not for union, but for love's own sake. The teaching is guarded, symbolic, and central.", application: "The gopi teaching is the library's most advanced devotional entry. The application is not imitation but understanding: love without possession, longing without demand, devotion without transaction. The practice is the quality, not the content.", questions: ["What is my relationship to love without possession?", "Where is my devotion transactional — and what would non-transactional devotion look like?", "Can I hold longing without demand?"], references: ["Bhagavata Purana 10.29-10.33", "Bhagavata Purana 10.34-10.35"], excerpt: "The gopis' love — not for reward, not for union, but for love's own sake.", evidence: "traditional", dimensions: ["emotion", "spirit"], paths: ["bhakti"], domains: ["spirituality", "relationships"], tags: ["bhagavata", "gopi", "rasa", "love", "longing", "highest_devotion"], difficulty: "advanced", minutes: 9 },
  { concept: "Uddhava's Instruction — The Final Teaching", tradition: "Bhagavata Purana", source: "Bhagavata Purana 11.6-11.29", explanation: "The Bhagavata's eleventh canto: Krishna's final instruction to Uddhava — the text's own summary of its teaching. Detachment, non-attachment to the modes, the nature of the soul, the process of liberation, and the bhakti that surpasses all. The canto is the Bhagavata's philosophical summit.", application: "Uddhava's instruction is the library's advanced curriculum: the eleventh canto's teachings on the soul's nature, the modes' mechanics, and devotion's supremacy. The application is study — slow, repeated, with practice.", questions: ["What is the soul's nature, according to the final teaching?", "How do the modes operate in my daily decisions?", "What does 'devotion surpasses all' mean for my practice hierarchy?"], references: ["Bhagavata Purana 11.6-11.29", "Bhagavata Purana 11.30-11.31"], excerpt: "The final instruction to Uddhava — the text's own summary.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["bhakti", "jnana"], domains: ["learning", "spirituality"], tags: ["bhagavata", "uddhava", "final_teaching", "eleventh_canto", "summit"], difficulty: "advanced", minutes: 10 },
  { concept: "The Bhagavata's Definition of Dharma", tradition: "Bhagavata Purana", source: "Bhagavata Purana 1.2.6", explanation: "The Bhagavata's famous definition: dharma is that which is spoken by the Lord, the supreme truth — and its fruit is devotion. The text distinguishes dharma from its imitations: ritual without devotion, ethics without love, action without surrender. The definition is the text's compass.", application: "Use the definition as a filter: does this action increase devotion — connection to the real — or merely its imitation? The filter applies to practice, work, and relationship alike.", questions: ["What is dharma's definition in my life — and what are its imitations?", "Where is ritual without devotion in my practice?", "What would devotion-as-fruit change about my daily choices?"], references: ["Bhagavata Purana 1.2.6", "Bhagavata Purana 1.2.7-1.2.10"], excerpt: "Dharma is that which is spoken by the Lord; its fruit is devotion.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["bhakti", "jnana"], domains: ["ethics", "spirituality"], tags: ["bhagavata", "dharma", "definition", "devotion", "filter", "imitation"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Four Regulative Principles", tradition: "Bhagavata Purana", source: "Bhagavata Purana 1.17; 11.5", explanation: "The Bhagavata's ethical frame, elaborated in the eleventh canto: non-violence, truthfulness, non-stealing, and continence — with the addition of non-intoxication in the tradition's later summaries. The principles are presented not as commandments but as the conditions for the mind's purification.", application: "The four principles are the library's ethical backbone for devotional practice. The application is practical: each principle is a purification condition — its observance is measured by the mind's clarity, not by the rule's letter.", questions: ["Which principle is most strained in my life?", "Is my observance measured by clarity or by rule?", "What is the difference between a commandment and a purification condition?"], references: ["Bhagavata Purana 1.17.1-1.17.40", "Bhagavata Purana 11.5.1-11.5.30"], excerpt: "Non-violence, truthfulness, non-stealing, continence — the conditions of purification.", evidence: "traditional", dimensions: ["action", "thought", "emotion"], paths: ["bhakti", "karma"], domains: ["ethics", "growth"], tags: ["bhagavata", "regulative", "principles", "non_violence", "truth", "purification"], difficulty: "beginner", minutes: 6 },
  { concept: "The Twenty-Four Avatars — The Descents", tradition: "Bhagavata Purana", source: "Bhagavata Purana 1.3", explanation: "The Bhagavata's first canto catalogs the twenty-four principal avatars — from the fish and tortoise to the sage and the future Buddha — each descent answering a specific cosmic need. The teaching: the divine descends not randomly but responsively, for the protection of the good and the restoration of dharma.", application: "The avatar catalog is the library's teaching on responsive action: the descent answers a need. The application is personal — what need is asking for my own 'descent' — my intervention, my presence, my stand?", questions: ["What need is asking for my descent — my intervention — right now?", "Which avatar's response most resembles my current challenge?", "What is the difference between a descent and an intrusion?"], references: ["Bhagavata Purana 1.3.1-1.3.28", "Bhagavata Purana 1.3.29-1.3.40"], excerpt: "The twenty-four descents — each answering a specific need.", evidence: "traditional", dimensions: ["spirit", "action", "thought"], paths: ["bhakti"], domains: ["spirituality", "purpose"], tags: ["bhagavata", "avatars", "twenty_four", "descent", "responsive", "protection"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Bhagavata's View of the World — Lila", tradition: "Bhagavata Purana", source: "Bhagavata Purana 1.1.1-1.1.3", explanation: "The Bhagavata opens with the declaration that the supreme truth is that from which everything proceeds, by which everything is sustained, and into which everything returns — and that its play (lila) is the world. The world is not illusion to be escaped but play to be participated in.", application: "The lila teaching is the library's corrective to escapist spirituality: the world is not a mistake to be transcended but a play to be entered. The application is participation — full, aware, ungrasping.", questions: ["Am I treating the world as mistake or as play?", "What would participation (not escape) look like today?", "Can I hold the world as lila — play — without losing its seriousness?"], references: ["Bhagavata Purana 1.1.1-1.1.3", "Bhagavata Purana 1.2.1-1.2.10"], excerpt: "The supreme truth, from which all proceeds, by which all is sustained, into which all returns — its play is the world.", evidence: "traditional", dimensions: ["spirit", "thought", "connection"], paths: ["bhakti", "jnana"], domains: ["spirituality", "growth"], tags: ["bhagavata", "lila", "play", "world", "participation", "not_escape"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Devotion of the Gopis — Beyond Rules", tradition: "Bhagavata Purana", source: "Bhagavata Purana 10.30-10.33", explanation: "The Bhagavata's most daring teaching: the gopis' devotion transcends rules, roles, and even propriety. Their love is presented as the summit — not because it breaks rules, but because it recognizes nothing but the beloved. The text guards this teaching carefully, presenting it as the fruit, not the method.", application: "The gopi teaching is the library's lesson on transcendence: the rules are the raft; the love is the far shore. The application is the discipline of sequence — the raft first, the shore later — and the humility to know the difference.", questions: ["Where am I mistaking the far shore for the raft?", "What is my practice's sequence — rules first, or recognition first?", "Can I hold the teaching's daring without its danger?"], references: ["Bhagavata Purana 10.30-10.33", "Bhagavata Purana 10.34-10.35"], excerpt: "Their love recognized nothing but the beloved — the summit, guarded as fruit, not method.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["bhakti"], domains: ["spirituality"], tags: ["bhagavata", "gopis", "beyond_rules", "transcendence", "summit", "guarded"], difficulty: "advanced", minutes: 9 },
  { concept: "The Liberation of the Mother — Kunti's Prayer", tradition: "Bhagavata Purana", source: "Bhagavata Purana 1.8", explanation: "The Bhagavata's first canto closes with Kunti's prayer — twenty-two verses of devotion, theology, and grief. She praises the Lord who is beyond the mind's reach, who appears as the world yet is not the world, who is the shelter of the surrendered. The prayer is the text's devotional summit.", application: "Kunti's prayer is the library's model of devotional expression: theology and grief in one breath. The application is permission — to pray with the whole mind, not the pious part.", questions: ["Can I pray with the whole mind — theology and grief together?", "What is my relationship to the shelter of surrender?", "Where is my devotion separated from my suffering?"], references: ["Bhagavata Purana 1.8.1-1.8.22", "Bhagavata Purana 1.9"], excerpt: "Kunti's prayer — twenty-two verses of devotion, theology, and grief.", evidence: "traditional", dimensions: ["emotion", "spirit", "thought"], paths: ["bhakti", "jnana"], domains: ["spirituality", "growth"], tags: ["bhagavata", "kunti", "prayer", "grief", "theology", "shelter"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Sage Narada — The Wandering Teacher", tradition: "Bhagavata Purana", source: "Bhagavata Purana 1.1; 6.3", explanation: "Narada, the wandering sage, appears throughout the Bhagavata — the teacher of teachers, the instigator of stories, the divine messenger who carries teachings between worlds. The text presents him as the living link between the tradition and the seeker.", application: "Narada's figure teaches the library's view of teachers: not settled authorities but wandering links — the teaching travels, and the teacher is its vehicle. The application is the seeker's posture: receptive to teachings arriving from unexpected directions.", questions: ["From what unexpected direction is my next teaching arriving?", "Am I a settled authority or a wandering link?", "What is the difference between a teacher and a vehicle?"], references: ["Bhagavata Purana 1.1.1-1.1.3", "Bhagavata Purana 6.3.1-6.3.50"], excerpt: "Narada, the wandering sage — the teaching's vehicle between worlds.", evidence: "traditional", dimensions: ["thought", "spirit", "connection"], paths: ["bhakti", "jnana"], domains: ["learning", "spirituality"], tags: ["bhagavata", "narada", "wandering", "teacher", "vehicle", "link"], difficulty: "beginner", minutes: 6 },
  { concept: "The Curse of the Kumaras — Liberation's Delay", tradition: "Bhagavata Purana", source: "Bhagavata Purana 3.15-3.16; 7.1", explanation: "The Bhagavata's cosmology includes the story of the four Kumaras — mind-born sons of Brahma — who, despite their purity, are cursed by the gatekeepers of Vishnu's abode to be born as mortals. The teaching: even the pure are not exempt from the play's consequences; liberation's delay is part of the play.", application: "The Kumaras' story teaches the library's patience lesson: purity does not exempt from process. The application is the acceptance of delay — the practice continues even when arrival is postponed.", questions: ["Where am I expecting exemption from process?", "What is my relationship to delay — resistance or acceptance?", "Can I practice without the promise of arrival's date?"], references: ["Bhagavata Purana 3.15-3.16", "Bhagavata Purana 7.1.1-7.1.10"], excerpt: "Even the pure are born as mortals. Liberation's delay is part of the play.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["jnana", "bhakti"], domains: ["spirituality", "growth"], tags: ["bhagavata", "kumaras", "curse", "delay", "patience", "process"], difficulty: "advanced", minutes: 8 },
  { concept: "The Universal Form — The Vision of the Whole", tradition: "Bhagavata Purana", source: "Bhagavata Purana 11.16; Bhagavad Gita 11", explanation: "The Bhagavata, echoing the Gita's eleventh chapter, teaches the universal form — the vision in which the whole is seen at once: all beings, all times, all worlds, in one view. The teaching's purpose is not spectacle but the dissolution of the viewer's separateness.", application: "The universal form is the library's largest contemplation. The application is not the vision itself but its preparation: the practices that widen attention until the whole becomes conceivable — and the viewer's separateness dissolves.", questions: ["What is my practice's largest address — the whole?", "Where is my attention trained on fragments when it could be trained on the whole?", "What is the difference between conceiving the whole and seeing it?"], references: ["Bhagavata Purana 11.16.1-11.16.50", "Bhagavad Gita 11.1-11.55"], excerpt: "The universal form — all beings, all times, all worlds, in one view.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["bhakti", "jnana"], domains: ["spirituality"], tags: ["bhagavata", "universal_form", "whole", "vision", "dissolution", "separateness"], difficulty: "advanced", minutes: 10 },
  { concept: "The Bhagavata's Conclusion — Bhakti Alone", tradition: "Bhagavata Purana", source: "Bhagavata Purana 12.13", explanation: "The Bhagavata closes with its conclusion: of all the paths — knowledge, action, yoga, meditation — devotion is declared the highest, because it alone returns the fruit to the Lord rather than to the practitioner. The text's final teaching is its first teaching, seen from the end.", application: "The conclusion is the library's devotional horizon: every practice — including this library's — is measured by whether its fruit returns to the whole or to the self. The application is the orientation, not the abandonment of practice.", questions: ["To whom does my practice's fruit return — the whole or the self?", "What would devotion-as-highest change about my practice hierarchy?", "Can I hold all paths as valid and one as highest — without contradiction?"], references: ["Bhagavata Purana 12.13.1-12.13.22", "Bhagavata Purana 1.1.1-1.1.3"], excerpt: "Of all paths, devotion is highest — it alone returns the fruit to the Lord.", evidence: "traditional", dimensions: ["spirit", "thought", "emotion"], paths: ["bhakti"], domains: ["spirituality"], tags: ["bhagavata", "conclusion", "bhakti", "highest", "fruit", "orientation"], difficulty: "advanced", minutes: 8 },
  { concept: "The Srimad Bhagavata's Opening — The Avatar's Descent", tradition: "Bhagavata Purana", source: "Bhagavata Purana 1.1.1-1.1.3", explanation: "The Bhagavata opens with its famous verse: the supreme truth, from which everything proceeds, by which everything is sustained, into which everything enters — that truth, the text declares, is now described. The opening is a declaration of scope: this text describes the whole.", application: "The opening teaches the library's ambition: a library that describes the whole — not fragments. The application is the reader's posture: approach each entry as part of a whole, not as a self-contained fragment.", questions: ["Am I reading entries as fragments or as parts of a whole?", "What is my practice's scope — the whole or the fragment?", "What does 'describing the whole' demand of my attention?"], references: ["Bhagavata Purana 1.1.1-1.1.3", "Bhagavata Purana 1.2.1-1.2.10"], excerpt: "The supreme truth, from which all proceeds, by which all is sustained, into which all enters — now described.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["bhakti", "jnana"], domains: ["spirituality", "learning"], tags: ["bhagavata", "opening", "avatar", "descent", "whole", "scope"], difficulty: "beginner", minutes: 6 },
  { concept: "The Devotion of the Animals — The Lion and the Elephant", tradition: "Bhagavata Purana", source: "Bhagavata Purana 8.2-8.4; 7.4", explanation: "The Bhagavata repeatedly tells of animals whose devotion surpasses humans': the elephant Gajendra, the lion-prince Narasimha's devotee Prahlada (a child), the birds, the bees. The teaching: devotion is not a human monopoly; the capacity is universal.", application: "The animal stories teach the library's democratic premise: awareness is not a human privilege. The application is the extension of practice's respect — to the body, the instincts, the non-human world.", questions: ["What can the animals' devotion teach my human practice?", "Where is my practice's respect extended — and where withheld?", "Is awareness a human monopoly or a universal capacity?"], references: ["Bhagavata Purana 8.2-8.4", "Bhagavata Purana 7.4.1-7.4.30"], excerpt: "The elephant, the child, the birds — devotion is not a human monopoly.", evidence: "traditional", dimensions: ["emotion", "spirit", "connection"], paths: ["bhakti"], domains: ["spirituality", "growth"], tags: ["bhagavata", "animals", "elephant", "lion", "universal", "democratic"], difficulty: "beginner", minutes: 6 },
  { concept: "The Bhagavata's View of Time — The Cosmic Cycle", tradition: "Bhagavata Purana", source: "Bhagavata Purana 3.10-3.12; 12.4", explanation: "The Bhagavata's cosmology: time (kala) as the divine's creative force, cycling through vast ages — the day of Brahma, the night of Brahma, the kalpas. The teaching: the cosmos is not a one-time event but a rhythm; time is not a line but a dance.", application: "The cosmic-cycle teaching is the library's patience foundation: the individual's arc is embedded in cycles vastly larger. The application is scale — the day's urgency, seen against the kalpa, becomes both smaller and more precious.", questions: ["What is my practice's relationship to time — line or cycle?", "How does the cosmic scale change today's urgency?", "What is both smaller and more precious, seen at the right scale?"], references: ["Bhagavata Purana 3.10-3.12", "Bhagavata Purana 12.4.1-12.4.80"], excerpt: "Time cycles through vast ages. The cosmos is a rhythm, not a line.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "bhakti"], domains: ["learning", "spirituality"], tags: ["bhagavata", "time", "cosmic_cycle", "kalpa", "rhythm", "scale"], difficulty: "intermediate", minutes: 8 },
];
